<?php
namespace App\Http\Controllers\Platform;
use App\Http\Controllers\Controller;use App\Models\Landlord\PlatformAuditEvent;use App\Models\Landlord\PlatformSupportCase;use Illuminate\Http\RedirectResponse;use Illuminate\Http\Request;use Illuminate\Support\Str;use Illuminate\View\View;
class PlatformSupportCaseController extends Controller {public function index():View{return view('platform.support.index',['cases'=>PlatformSupportCase::query()->with('tenant')->latest('forwarded_at')->get(),'attentionCount'=>PlatformSupportCase::query()->whereIn('status',['forwarded','under_review'])->count()]);}public function update(Request $request,PlatformSupportCase $case):RedirectResponse{$data=$request->validate(['status'=>['required','in:forwarded,under_review,planned,in_progress,released,declined'],'platform_note'=>['nullable','string','max:5000']]);$before=$case->status;$case->fill($data);if(filled($data['platform_note']??null))$case->platform_replied_at=now();$case->save();PlatformAuditEvent::query()->create(['uuid'=>(string)Str::uuid(),'platform_administrator_id'=>$request->user('platform')->id,'tenant_id'=>$case->tenant_id,'event'=>'platform_support_case_updated','properties'=>['case_id'=>$case->id,'before_status'=>$before,'after_status'=>$case->status,'replied'=>filled($data['platform_note']??null)],'ip_address'=>$request->ip()]);return back()->with('status','Platform case updated.');}}
